#[test]
fn sqlite_snapshot_semio_image_pixels_metadata_profiles_colorspaces_and_native_state(){let snapshot=fixture();let bytes=export_sqlite_database(&project(&snapshot),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let restored=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(restored,snapshot);assert_eq!(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&restored),<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&snapshot));assert_eq!(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&restored),<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&snapshot));for colorspace in [SemioColorspace::Rgb,SemioColorspace::Rgba,SemioColorspace::Grayscale,SemioColorspace::GrayscaleAlpha,SemioColorspace::Indexed]{for icc in [None,Some(Vec::new())]{let mut value=SemioImageSnapshot::default();value.colorspace=colorspace;value.icc=icc;assert_eq!(restore(&project(&value)).unwrap(),value);}}let value=SemioImageSnapshot{width:u32::MAX,height:u32::MAX,..SemioImageSnapshot::default()};assert_eq!(restore(&project(&value)).unwrap(),value);}
#[test]
fn sqlite_snapshot_semio_image_rejects_pixel_shape_scalar_foreign_key_and_budget_corruption(){let original=project(&fixture());for change in 0..4{let mut db=original.clone();match change{0=>db.table_mut("semio_image_frame").unwrap().rows[0].values[1]=SqliteValue::Integer(999),1=>db.table_mut("semio_image_frame").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>db.table_mut("semio_image_sample").unwrap().rows[0].values[3]=SqliteValue::Integer(4),_=>db.table_mut("semio_image_document").unwrap().rows[0].values[5]=SqliteValue::Integer(256)}assert!(restore(&db).is_err());}let limits=SqliteDatabaseLimits{max_rows:1,max_value_bytes:1,..SqliteDatabaseLimits::default()};assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(SemioImageSnapshot::from_sqlite_database(&original,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}
#[test]
fn sqlite_snapshot_semio_image_independent_pixels_query_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');if(JSON.stringify(db.query('SELECT s.sample FROM semio_image_sample s JOIN semio_image_frame f ON f.id=s.frame_id WHERE f.ordinal=1 ORDER BY s.ordinal').all().map(row=>row.sample))!==JSON.stringify([255,0,0,255,0,255,0,127])||db.query('SELECT hex(icc) profile FROM semio_image_document').get().profile!=='0001FF')throw Error('pixels/profile');db.query('UPDATE semio_image_frame SET delay_ms=1234 WHERE ordinal=1').run();await Bun.write(Bun.stdout,db.serialize());db.close();";let mut child=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let out=child.wait_with_output().unwrap();assert!(out.status.success(),"{}",String::from_utf8_lossy(&out.stderr));let restored=restore(&import_sqlite_database(&out.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();let mut expected=fixture();expected.frames[1].delay_ms=1234;assert_eq!(restored,expected);}

