fn sqlite_snapshot_semio_image_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|semio_framework_artifact_reference::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_image_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_image_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"image".into()};
    let provider=<SemioImageSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let database=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();
        let actual=(provider.import)("Semio native admission",&dialect,database,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());
        assert!(snapshot.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());
    }
    let large= SemioImageSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()})).is_err());
    assert!(large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,&mut SqliteSnapshotControl::new(&mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0,SqliteDatabaseLimits::default())).is_err());
}

#[test]
fn sqlite_snapshot_semio_image_explicit_controlled_native_owner(){
 let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let admission=&f["controlledAdmission"];let mut source=fixture();source.metadata=vec![source.metadata[0].clone();admission["collectionItems"].as_u64().unwrap() as usize];for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&source))};assert_eq!(SemioImageSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),source);assert!(SemioImageSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());let mut interior=false;let error=SemioImageSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |p|{if p.phase==SqliteSnapshotPhase::DecodeNative&&p.total==admission["collectionItems"].as_u64().unwrap() as usize&&p.completed==admission["cancelAfter"].as_u64().unwrap() as usize{interior=true;false}else{true}},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior);assert!(error.message.contains("canceled"));}
 source.icc=Some(vec![0xff;admission["largeBytes"].as_u64().unwrap() as usize]);for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{let payload=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&source)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&source))};assert!(SemioImageSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:admission["smallOwnedBytes"].as_u64().unwrap() as usize,..SqliteDatabaseLimits::default()})).is_err());}
}

#[test]
fn sqlite_snapshot_semio_image_controlled_native_output(){let f:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let mut s=fixture();s.metadata[0].value="x".repeat(f["nativeOutputBytes"].as_u64().unwrap() as usize);for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap();let expected=match encoding{SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&s)),SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&s))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");for measured in [false,true]{let mut interior=false;let error=s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::EncodeNative&&event.completed>=65536&&(if measured{event.total==0}else{event.total>65536&&event.completed<event.total});interior|=cancel;!cancel},SqliteDatabaseLimits::default())).unwrap_err();assert!(interior&&error.message.contains("cancel"),"{error}");}for limits in [SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_file_bytes:4096,..SqliteDatabaseLimits::default()},SqliteDatabaseLimits{max_rows:0,..SqliteDatabaseLimits::default()}]{assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,limits)).is_err());}assert!(s.encode_sqlite_snapshot_native(encoding,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());}}

#[test]
fn sqlite_snapshot_semio_image_erased_complete_ordered_samples_and_intermediate_owners(){
 use std::io::Write;use std::process::{Command,Stdio};
 let neutral:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🎨️samples/🔣️.json")).unwrap();
 let provider=<SemioImageSnapshot as store::ArtifactPack>::sqlite_snapshot_codec().unwrap();
 let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"image".into()};
 for case in neutral["cases"].as_array().unwrap(){
  let input=&case["snapshot"];let snapshot=SemioImageSnapshot{schema:input["schema"].as_str().unwrap().into(),width:u32::try_from(input["width"].as_u64().unwrap()).unwrap(),height:u32::try_from(input["height"].as_u64().unwrap()).unwrap(),colorspace:SemioColorspace::Indexed,bit_depth:u8::try_from(input["bitDepth"].as_u64().unwrap()).unwrap(),icc:Some(Vec::new()),frames:input["frames"].as_array().unwrap().iter().map(|frame|SemioImageFrame{delay_ms:u32::try_from(frame["delayMs"].as_u64().unwrap()).unwrap(),rgba8:frame["rgba8"].as_array().unwrap().iter().map(|value|u8::try_from(value.as_u64().unwrap()).unwrap()).collect()}).collect(),metadata:input["metadata"].as_array().unwrap().iter().map(|entry|SemioImageMetadataEntry{key:entry["key"].as_str().unwrap().into(),value:entry["value"].as_str().unwrap().into()}).collect()};
  for encoding in [SnapshotEncoding::Text,SnapshotEncoding::Binary]{
   let payload=match encoding{SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioImageSnapshot as store::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioImageSnapshot as store::ArtifactPack>::encode_pack(&snapshot))};
   let database=(provider.export)("s.stdio.semio.image",&dialect,&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
   assert_eq!(restore(&database).unwrap(),snapshot);
   let bytes=export_sqlite_database(&database,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
   let script="import{Database}from'bun:sqlite';const expected=JSON.parse(process.argv[1]);const db=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));try{if(db.query('PRAGMA integrity_check').get().integrity_check!=='ok'||db.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const rows=db.query('SELECT ordinal,channel,sample FROM semio_image_sample ORDER BY frame_id,ordinal').all();if(JSON.stringify(rows)!==JSON.stringify(expected.map((sample,ordinal)=>({ordinal,channel:ordinal%4,sample}))))throw Error('samples');if(expected.length>2)db.query('UPDATE semio_image_sample SET sample=42 WHERE ordinal=2').run();await Bun.write(Bun.stdout,db.serialize());}finally{db.close();}";
   let expected_bytes=serde_json::to_string(&snapshot.frames[0].rgba8).unwrap();
   let mut child=Command::new("bun").args(["-e",script,&expected_bytes]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();child.stdin.take().unwrap().write_all(&bytes).unwrap();let output=child.wait_with_output().unwrap();assert!(output.status.success(),"{}",String::from_utf8_lossy(&output.stderr));
   let edited=import_sqlite_database(&output.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();
   let mut expected=snapshot.clone();if expected.frames[0].rgba8.len()>2{expected.frames[0].rgba8[2]=42;}
   assert_eq!(restore(&edited).unwrap(),expected);
   let result=(provider.import)("s.stdio.semio.image",&dialect,edited,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;
   assert_eq!(SemioImageSnapshot::decode_sqlite_snapshot_native(&result,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap(),expected);
  }
 }
 println!("[DEBUG] Semio image erased Text and Binary owners preserve independently edited ordered channel samples across complete, empty, partial and overflow states");
}

